t:space-between;margin-bottom:6px;letter-spacing:1.8px;font-size:12px}.level-pill{letter-spacing:.5px;color:#f6dfa0;font-size:9px;padding:3px 6px;border-radius:6px;background:rgba(230,196,119,.15);border:1px solid rgba(230,196,119,.2)}.meter-row{display:flex;align-items:center;gap:5px;height:11px}.meter-row small{width:53px;text-align:right;font-size:8px;color:#d4ddd1;white-space:nowrap}.heart{color:#f18a7e;font-size:10px}.xp-star{color:#ebd179;font-size:10px}.meter{height:6px;border-radius:7px;overflow:hidden;flex:1;background:rgba(8,17,20,.62);box-shadow:inset 0 1px 2px #0007}.meter i{height:100%;display:block;width:100%;border-radius:8px;transition:width .25s}.hp-meter i{background:linear-gradient(90deg,#e77a70,#f4a580);box-shadow:0 0 8px #f28a7555}.xp-meter{height:4px}.xp-meter i{background:linear-gradient(90deg,#e5c365,#fbebae)}.xp-row{margin-top:5px}.quest-card{height:78px;min-width:300px;max-width:350px;flex:1;border-radius:15px;display:flex;align-items:center;padding:12px 14px;gap:12px}.quest-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:12px;color:#f3dc98;background:linear-gradient(145deg,rgba(220,192,117,.2),rgba(94,117,89,.2));font-size:25px}.quest-copy{display:grid;gap:3px;min-width:0;flex:1}.eyebrow{font-size:8px;letter-spacing:1.8px;color:#d5c786;font-weight:700}.quest-copy strong{font-family:Marcellus,serif;font-size:15px;font-weight:400}.quest-copy>span:last-child{font-size:10px;color:#bdcbbf;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.quest-count{color:#ecd687;font-family:Marcellus,serif;font-size:20px;padding:0 3px}.quest-count i{font-style:normal;color:#aab8a9;font-size:12px}.right-tools{margin-left:auto;display:grid;grid-template-columns:1fr 40px 40px;gap:8px;justify-items:end;align-items:start}.weather-pill{height:34px;border-radius:18px;padding:0 12px;display:flex;align-items:center;gap:7px;font-size:8px;letter-spacing:1px;color:#d3decf;white-space:nowrap}.weather-dot{width:7px;height:7px;border-radius:50%;background:#a2d8ab;box-shadow:0 0 10px #9ee2ad}.icon-button{width:36px;height:34px;border-radius:11px;border-color:rgba(231,227,195,.17);font-size:15px;color:#e6d69d;cursor:pointer}.icon-button:hover{background:#46544a}.minimap{grid-column:1/4;position:relative;width:156px;height:116px;border-radius:12px;overflow:hidden;padding:0}.minimap canvas{width:100%;height:100%;opacity:.9}.map-label{position:absolute;left:8px;bottom:6px;font-size:7px;letter-spacing:1.4px;text-shadow:0 1px 4px #000}.bottom-ui{position:absolute;z-index:2;inset:auto 24px 20px;display:flex;align-items:end;justify-content:space-between;pointer-events:none}.controls-hint,.quickbar,.objective-chip{pointer-events:auto}.controls-hint{border-radius:10px;padding:9px 13px;color:#d3ddd3;font-size:9px;letter-spacing:.1px}.controls-hint kbd,.guide-grid kbd{font-family:inherit;font-weight:700;font-size:8px;padding:4px 5px;border-radius:4px;border:1px solid #d5d4bd44;background:#182528;color:#f1e2b4;box-shadow:0 2px #080f11;margin-right:4px}.controls-hint span{padding:0 7px;color:#a2af9f}.quickbar{position:absolute;bottom:0;left:50%;transform:translateX(-50%);height:57px;border-radius:13px;display:flex;align-items:center;padding:6px;gap:5px}.quick-slot{width:43px;height:43px;position:relative;border-radius:9px;border:1px solid rgba(240,232,200,.22);background:rgba(9,19,22,.48);display:grid;place-items:center}.active-slot{border-color:rgba(239,207,129,.75);box-shadow:0 0 12px #e4c4772b,inset 0 0 10px #e4c47714}.slot-key{position:absolute;top:2px;left:4px;font-size:7px;color:#c5c6b7}.slot-art{font-size:19px;color:#a7d7c0;text-shadow:0 0 10px #87dbb2}.slot-art.potion{color:#e4a599}.quick-slot b{position:absolute;right:4px;bottom:2px;font-size:8px;color:#f3e7c2}.empty-slot .slot-art{font-size:15px;color:#65756d}.quick-separator{height:30px;width:1px;background:var(--line);margin:0 5px}.weapon-slot{height:43px;display:flex;align-items:center;gap:8px;padding:0 6px}.weapon-art{color:#e8d18c;font-size:22px;text-