66px;right:0;bottom:18px;background:radial-gradient(circle at 35% 24%,#c67e63,#77433f 75%);border-color:#f1c39b88}.dodge-button{width:51px;height:51px;right:70px;bottom:0}.potion-button{width:48px;height:48px;right:73px;top:0;background:radial-gradient(circle at 35% 25%,#bd827e,#684952 75%)}.potion-button span{font-size:16px;line-height:18px}.potion-button small{font-size:6px}.modal{padding:28px 25px 22px}.modal h2{font-size:24px}.modal p{font-size:11px}.guide-grid{margin:16px 0 19px}.guide-grid kbd{font-size:7px;padding:6px 5px}.location-toast{top:26%}}
