(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const mapCanvas = document.getElementById('map');
  const mapCtx = mapCanvas.getContext('2d');
  const shell = document.getElementById('game-shell');
  const WORLD = { w: 2100, h: 1450 };
  const player = { x: 470, y: 680, r: 15, faceX: 1, faceY: 0, speed: 205, hp: 100, maxHp: 100, xp: 0, level: 1, potions: 2, shards: 0, attack: 12, attackCd: 0, attackAnim: 0, dodge: 0, invuln: 0, walk: 0 };
  let W = innerWidth, H = innerHeight, dpr = 1, last = 0, elapsed = 0, paused = true, won = false;
  let toastTimer = 0, locationTimer = 0, locationShown = false, soundOn = false;
  const camera = { x: 0, y: 0 };
  const keys = new Set();
  const input = { x: 0, y: 0 };
  const effects = [], entities = [], trees = [], shards = [], enemies = [];
  const terrain = document.createElement('canvas'); terrain.width = WORLD.w; terrain.height = WORLD.h;
  const tctx = terrain.getContext('2d');
  const hash = (x, y) => { let n = (x * 374761393 + y * 668265263) | 0; n = Math.imul(n ^ (n >>> 13), 1274126177); return ((n ^ (n >>> 16)) >>> 0) / 4294967295; };
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
  const pathDistance = (x, y) => {
    const lines = [[-80,760,350,770,720,510,1040,540],[1040,540,1260,570,1460,500,1650,450],[980,550,1150,770,1360,850,1510,960],[420,770,590,950,850,1030,1040,1140]];
    let best = Infinity;
    for (const [x1,y1,x2,y2,x3,y3,x4,y4] of lines) for (let i=0;i<=24;i++) { const t=i/24, u=1-t, px=u*u*u*x1+3*u*u*t*x2+3*u*t*t*x3+t*t*t*x4, py=u*u*u*y1+3*u*u*t*y2+3*u*t*t*y3+t*t*t*y4; best=Math.min(best,Math.hypot(px-x,py-y)); }
    return best;
  };

  function buildTerrain() {
    const g = tctx.createLinearGradient(0,0,WORLD.w,WORLD.h); g.addColorStop(0,'#527855'); g.addColorStop(.5,'#476e52'); g.addColorStop(1,'#365e4b'); tctx.fillStyle=g; tctx.fillRect(0,0,WORLD.w,WORLD.h);
    // Soft pools of light across the mossy forest floor.
    for(let i=0;i<34;i++){const x=hash(i,8)*WORLD.w,y=hash(i,15)*WORLD.h,r=90+hash(i,23)*170;const glow=tctx.createRadialGradient(x,y,0,x,y,r);glow.addColorStop(0,'rgba(191,191,112,.09)');glow.addColorStop(1,'rgba(191,191,112,0)');tctx.fillStyle=glow;tctx.fillRect(x-r,y-r,r*2,r*2);}
    // Flecks of grass and tiny flowers, deterministic so the landscape stays still.
    for(let i=0;i<19000;i++){const x=hash(i,31)*WORLD.w,y=hash(i,47)*WORLD.h;if(pathDistance(x,y)<43)continue;const n=hash(i,59);tctx.fillStyle=n>.83?'rgba(216,210,137,.32)':n>.53?'rgba(178,198,131,.2)':'rgba(24,60,45,.13)';tctx.beginPath();tctx.ellipse(x,y,1+n*2,1.3,hash(i,83)*3,0,Math.PI*2);tctx.fill();if(n>.985){tctx.fillStyle='#eddc9c';tctx.fillRect(x,y,2,2);}}
    // Winding golden footpaths.
    tctx.lineCap='round';tctx.lineJoin='round';
    const paths=[[-80,760,350,770,720,510,1040,540],[1040,540,1260,570,1460,500,1650,450],[980,550,1150,770,1360,850,1510,960],[420,770,590,950,850,1030,1040,1140]];
    for(const p of paths){tctx.beginPath();tctx.moveTo(p[0],p[1]);tctx.bezierCurveTo(...p.slice(2));tctx.strokeStyle='rgba(29,62,47,.28)';tctx.lineWidth=94;tctx.stroke();tctx.strokeStyle='#b89e68';tctx.lineWidth=77;tctx.stroke();tctx.strokeStyle='#c9b17c';tctx.lineWidth=64;tctx.stroke();tctx.strokeStyle='rgba(241,220,165,.13)';tctx.lineWidth=3;tctx.stroke();}
    // Shallow, luminous pond.
    tctx.save();tctx.translate(1575,1010);tctx.rotate(-.16);const water=tctx.createRadialGradient(-45,-35,12,0,0,230);water.addColorStop(0,'#82b7a0');water.addColorStop(.55,'#568f83');water.addColorStop(1,'#366b68');tctx.fillStyle=water;tctx.beginPath();tctx.ellipse(0,0,230,150,0,0,Math.PI*2);tctx.fill();tctx.strokeStyle='#b8ca8c';tctx.lineWidth=8;tctx.stroke();for(let i=0;i<20;i++){let x=(hash(i,991)-.5)*330,y=(hash(i,997)-.5)*190;tctx.strokeStyle='rgba(212,236,190,.22)';tctx.lineWidth=2;tctx.beginPath();tctx.ellipse(x,y,8+hash(i,1003)*22,2,0,0,Math.PI*2);tctx.stroke();}tctx.restore();
    // Natural map border and darker forest edge.
    const edge=tctx.createRadialGradient(1050,700,600,1050,700,1280);edge.addColorStop(0,'rgba(0,0,0,0)');edge.addColorStop(1,'rgba(13,36,35,.46)');tctx.fillStyle=edge;tctx.fillRect(0,0,WORLD.w,WORLD.h);
    for(let i=0;i<260;i++){const side=i%4, u=hash(i,1120), x=side<2?u*WORLD.w:(side===2?18:WORLD.w-18), y=side>=2?u*WORLD.h:(side===0?18:WORLD.h-18);addTree(x,y,1.15+hash(i,1140)*.5,true);}
    // Interior woodland in loose groves; keep the trails and clearings open.
    for(let row=0;row<11;row++)for(let col=0;col<16;col++){const x=90+col*126+(hash(row,col)-.5)*86,y=95+row*119+(hash(col,row+80)-.5)*76;if(pathDistance(x,y)<106)continue;if(Math.hypot(x-470,y-680)<205||Math.hypot(x-1650,y-450)<190||Math.hypot(x-1575,y-1010)<225)continue;if(x>1370&&y>820)continue;addTree(x,y,.76+hash(row+40,col)*.62,false);}
  }
  function addTree(x,y,s,edge=false){trees.push({type:'tree',x,y,s,edge,r:21*s});}

  function setupWorld(){
    buildTerrain();
    // The woodland camp, a safe first landmark.
    entities.push({type:'cabin',x:330,y:595});
    entities.push({type:'campfire',x:462,y:650});
    entities.push({type:'npc',x:376,y:710,name:'Mira'});
    // Ancient altar at the end of the winding trail.
