  function attack(){if(paused||player.attackCd>0)return;player.attackCd=.42;player.attackAnim=.27;effects.push({type:'slash',x:player.x,y:player.y,life:.27,max:.27,dx:player.faceX,dy:player.faceY});for(const e of enemies){if(e.dead)continue;const dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),dot=(dx*player.faceX+dy*player.faceY)/(d||1);if(d<78&&dot>-.28){e.hp-=player.attack;e.hit=.22;effects.push({type:'hit',x:e.x,y:e.y,life:.28,max:.28});if(e.hp<=0)killEnemy(e);}}}
