function update(dt){
  elapsed+=dt;player.attackCd=Math.max(0,player.attackCd-dt);player.attackAnim=Math.max(0,player.attackAnim-dt);player.dodge=Math.max(0,player.dodge-dt);player.invuln=Math.max(0,player.invuln-dt);
  if(toastTimer>0&&(toastTimer-=dt)<=0)document.getElementById('toast').classList.remove('show');
  if(paused){updateCamera(dt);return;}
  let ix=input.x,iy=input.y;if(keys.has('a')||keys.has('arrowleft'))ix-=1;if(keys.has('d')||keys.has('arrowright'))ix+=1;if(keys.has('w')||keys.has('arrowup'))iy-=1;if(keys.has('s')||keys.has('arrowdown'))iy+=1;
  const mag=Math.hypot(ix,iy);if(mag>1){ix/=mag;iy/=mag;}if(Math.abs(ix)+Math.abs(iy)>.05){player.faceX=ix;player.faceY=iy;player.walk+=dt*11;}
  const speed=player.dodge>0?420:player.speed;let nx=clamp(player.x+ix*speed*dt,32,WORLD.w-32),ny=clamp(player.y+iy*speed*dt,40,WORLD.h-35);
  // Trees and stones are solid, but the winding trails remain broad and easy to navigate.
  for(const t of trees){const dx=nx-t.x,dy=ny-t.y,d=Math.hypot(dx,dy),min=t.r+player.r*.7;if(d<min&&d>0){nx=t.x+dx/d*min;ny=t.y+dy/d*min;}}
  for(const o of entities){if(o.type!=='rock')continue;const r=15*(o.s||1),d=Math.hypot(nx-o.x,ny-o.y);if(d<r+player.r&&d>0){nx=o.x+(nx-o.x)/d*(r+player.r);ny=o.y+(ny-o.y)/d*(r+player.r);}}
  player.x=nx;player.y=ny;
  for(const s of shards){if(!s.collected&&Math.hypot(player.x-s.x,player.y-s.y)<40){s.collected=true;player.shards++;player.xp+=8;effects.push({type:'collect',x:s.x,y:s.y,life:.8,max:.8});showToast(`Fragmento de aurora encontrado  ·  ${player.shards}/3`);checkLevel();updateHud();if(player.shards===3){document.getElementById('quest-title').textContent='O altar antigo';document.getElementById('quest-description').textContent='Leve os fragmentos até o altar';document.getElementById('objective-distance').textContent='Encontre o altar';}}}
  for(const e of enemies){if(e.dead)continue;e.phase+=dt*3;e.hit=Math.max(0,e.hit-dt);e.attackCd-=dt;const d=dist(player,e);if(d<310&&d>28){const dx=(player.x-e.x)/d,dy=(player.y-e.y)/d;let ex=e.x+dx*e.speed*dt,ey=e.y+dy*e.speed*dt;for(const t of trees){const td=Math.hypot(ex-t.x,ey-t.y),min=t.r+e.r*.72;if(td<min){ex-=dx*e.speed*dt*.9;ey-=dy*e.speed*dt*.9;break;}}e.x=ex;e.y=ey;}else if(d<=32&&e.attackCd<=0&&player.invuln<=0){e.attackCd=1.15;player.hp=Math.max(0,player.hp-9);player.invuln=.7;effects.push({type:'hurt',x:player.x,y:player.y,life:.3,max:.3});updateHud();if(player.hp<=0){player.hp=player.maxHp;player.x=470;player.y=680;player.shards=Math.max(0,player.shards-1);updateHud();showToast('Você voltou ao acampamento  ·  um fragmento se perdeu');}}
  }
  for(let i=effects.length-1;i>=0;i--){effects[i].life-=dt;if(effects[i].life<=0)effects.splice(i,1);}
  updateCamera(dt);
  const goal=player.shards>=3?entities.find(e=>e.type==='shrine'):shards.find(s=>!s.collected);if(goal){const d=Math.round(dist(player,goal));document.getElementById('objective-distance').textContent=player.shards>=3?`Altar · ${d} m`:`Fragmento · ${d} m`;}
  if(!locationShown&&player.x>650){locationShown=true;const el=document.getElementById('location-toast');el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800);}
}
